<script setup lang="ts">import {computed} from 'vue';import * as api from '../api/runs';import {useResource} from '../hooks/useResource';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import SurveyMap from '../components/SurveyMap.vue';import CoverageSummary from '../components/CoverageSummary.vue';const {data,error}=useResource(api.list,[]);const run=computed(()=>data.value.find(r=>r.id==='run-baseline')||data.value.find(r=>r.status==='completed'));</script><template><PageTitle chapter="01" title="把有限补给，放在需要的地方" description="野渡湿地巡护队 · 秋季补给点覆盖预演。先看未覆盖需求，再讨论预算与取舍。"/><Notice :error="error"/><template v-if="run"><CoverageSummary :result="run.result"/><div class="map-layout"><SurveyMap :result="run.result"/><aside class="map-sidebar"><p class="eyebrow">拟选点位 / FIELD NOTES</p><h2>{{run.result.selected.length}} 处落点</h2><article v-for="(c,i) in run.result.selected" :key="c.id"><span>{{String(i+1).padStart(2,'0')}}</span><div><b>{{c.name}}</b><small>{{c.cost}} 万元 · {{c.latitude.toFixed(3)}}°N</small></div></article><p class="annotation">覆盖按球面直线距离计算，示意图不含实际航道障碍。最终落点仍需现场勘察。</p></aside></div></template><EmptyState v-else text="先导入巡护需求，核查候选点并建立预算方案。"/></template>
